+                    <div class="col-md-4 d-flex align-items-end">
+                        <div class="form-check">
+                            <input type="checkbox" class="form-check-input" checked="@workEntries[index].IsCurrent"
+                                   @onchange="e => { workEntries[index].IsCurrent = (bool)(e.Value ?? false); if (workEntries[index].IsCurrent) workEntries[index].EndDate = null; }" />
+                            <label class="form-check-label">Currently working here</label>
+                        </div>
+                    </div>
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Description</label>
+                    <textarea class="form-control" rows="3" value="@workEntries[index].Description"
+                              @onchange="e => workEntries[index].Description = e.Value?.ToString() ?? string.Empty"></textarea>
+                </div>
+                @if (workEntries.Count > 1)
+                {
+                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                }
+            </div>
+        }
+        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+        </div>
+    }
+
+    <!-- Step 3: References -->
+    @if (currentStep == 2)
+    {
+        <h3>References</h3>
+        @for (int i = 0; i < references.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <h5>Reference @(index + 1)</h5>
+                <div class="mb-2">
+                    <label class="form-label">Name *</label>
+                    <input class="form-control" value="@references[index].Name"
+                           @onchange="e => references[index].Name = e.Value?.ToString() ?? string.Empty" />
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Relationship *</label>
+                    <input class="form-control" value="@references[index].Relationship"
+                           @onchange="e => references[index].Relationship = e.Value?.ToString() ?? string.Empty" />
+                </div>
+                <div class="row mb-2">
+                    <div class="col-md-6">
+                        <label class="form-label">Email *</label>
+                        <input type="email" class="form-control" value="@references[index].Email"
+                               @onchange="e => references[index].Email = e.Value?.ToString() ?? string.Empty" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">Phone *</label>
+                        <input type="tel" class="form-control" value="@references[index].Phone"
+                               @onchange="e => references[index].Phone = e.Value?.ToString() ?? string.Empty" />
+                    </div>
+                </div>
+                @if (references.Count > 2)
+                {
+                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                }
+            </div>
+        }
+        @if (references.Count < 3)
+        {
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+        </div>
+    }
+
+    <!-- Step 4: Cover Letter -->
+    @if (currentStep == 3)
+    {
+        <h3>Cover Letter</h3>
+        <div class="mb-3">
+            <textarea class="form-control" rows="12" maxlength="2000" @bind="coverLetter"></textarea>
+            <small class="text-muted">@coverLetter.Length / 2000 characters</small>
+        </div>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
+        </div>
+    }
+
+    <!-- Step 5: Review & Submit -->
+    @if (currentStep == 4)
+    {
+        <h3>Review &amp; Submit</h3>
+
+        <div class="card mb-3 p-3">
+            <div class="d-flex justify-content-between align-items-center">
+                <h5>Personal Information</h5>
+                <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
+            </div>
+            <dl class="row mb-0">
+                <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@fullName</dd>
+                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@email</dd>
+                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@phone</dd>
+                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@address</dd>
+            </dl>
+        </div>
+
+        <div class="card mb-3 p-3">
+            <div class="d-flex justify-content-between align-items-center">
+                <h5>Work History</h5>
+                <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
+            </div>
+            @foreach (var entry in workEntries)
+            {
+                <div class="mb-2 ps-2 border-start">
+                    <strong>@entry.Title</strong> at @entry.Company<br />
+                    <small>@entry.StartDate?.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</small>
+                    @if (!string.IsNullOrWhiteSpace(entry.Description))
+                    {
+                        <p class="mb-0 mt-1">@entry.Description</p>
+                    }
+                </div>
+            }
+        </div>
+
+        <div class="card mb-3 p-3">
+            <div class="d-flex justify-content-between align-items-center">
+                <h5>References</h5>
+                <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
+            </div>
+            @foreach (var reference in references)
+            {
+                <div class="mb-2 ps-2 border-start">
+                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                    <small>@reference.Email | @reference.Phone</small>
+                </div>
+            }
+        </div>
+
+        <div class="card mb-3 p-3">
+            <div class="d-flex justify-content-between align-items-center">
+                <h5>Cover Letter</h5>
+                <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
+            </div>
+            <p style="white-space: pre-wrap;">@coverLetter</p>
+        </div>
+
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isProcessing">
+                @if (isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
+            </button>
+        </div>
+    }
+}
+
+<style>
+    .step-indicator ol {
+        padding: 0;
+        margin: 0;
+    }
+    .step-item {
+        display: flex;
+        flex-direction: column;
+        align-items: center;
+        flex: 1;
+        text-align: center;
+        position: relative;
+    }
+    .step-badge {
+        width: 36px;
+        height: 36px;
+        border-radius: 50%;
+        display: flex;
+        align-items: center;
+        justify-content: center;
+        font-weight: bold;
+        background-color: #e9ecef;
+        color: #6c757d;
+        margin-bottom: 4px;
+    }
+    .step-label {
+        font-size: 0.8rem;
+        color: #6c757d;
+    }
+    .step-item.active .step-badge {
+        background-color: #0d6efd;
+        color: white;
+    }
+    .step-item.active .step-label {
+        color: #0d6efd;
+        font-weight: bold;
+    }
+    .step-item.completed .step-badge {
+        background-color: #198754;
+        color: white;
+        cursor: pointer;
+    }
+    .step-item.completed .step-label {
+        color: #198754;
+        cursor: pointer;
+    }
+</style>
+
+@code {
+    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int currentStep = 0;
+    private int highestStepReached = 0;
+    private bool isProcessing = false;
+    private bool submitted = false;
+    private int applicationId = 0;
+    private string errorMessage = string.Empty;
+
+    // Step 1: Personal Info
+    private string fullName = string.Empty;
+    private string email = string.Empty;
+    private string phone = string.Empty;
+    private string address = string.Empty;
+
+    // Step 2: Work History
+    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string coverLetter = string.Empty;
+
+    private string GetStepClass(int step)
+    {
+        if (step == currentStep) return "active";
+        if (step < highestStepReached || (submitted && step <= 4)) return "completed";
+        return string.Empty;
+    }
+
+    private bool IsStepCompleted(int step) => step < highestStepReached;
+
+    private void GoToStep(int step)
+    {
+        if (step < highestStepReached)
+        {
+            errorMessage = string.Empty;
+            currentStep = step;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        errorMessage = string.Empty;
+        if (currentStep > 0) currentStep--;
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        errorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
+            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
+        {
+            errorMessage = "All fields are required.";
+            return;
+        }
+
+        isProcessing = true;
+        try
+        {
+            var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
+            if (!isValidEmail)
+            {
+                errorMessage = "The email address is not valid.";
+                return;
+            }
+            AdvanceStep();
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+    }
+
+    private void NextFromWorkHistory()
+    {
+        errorMessage = string.Empty;
+
+        foreach (var entry in workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
+            {
+                errorMessage = "Each position requires a company, title, and start date.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    private void NextFromReferences()
+    {
+        errorMessage = string.Empty;
+
+        foreach (var reference in references)
+        {
+            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship)
+                || string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
+            {
+                errorMessage = "All reference fields are required.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    private void NextFromCoverLetter()
+    {
+        errorMessage = string.Empty;
+        AdvanceStep();
+    }
+
+    private void AdvanceStep()
+    {
+        currentStep++;
+        if (currentStep > highestStepReached)
+            highestStepReached = currentStep;
+    }
+
+    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (workEntries.Count > 1) workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (references.Count < 3) references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (references.Count > 2) references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        isProcessing = true;
+        errorMessage = string.Empty;
+        try
+        {
+            var personal = new PersonalInfo(fullName, email, phone, address);
+            var work = new WorkHistory(workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, work, refs, coverLetter);
+
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            submitted = true;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+
